let currentUser=null, bookings=[], master={programs:[],addOns:[]}, passengers=[], editingCode=null, selectedBooking=null;
const INACTIVITY_LIMIT_MS=15*60*1000,ACTIVITY_KEY="sabinaLastActivity";
let lastActivityWrite=0;
function recordActivity(){if(!localStorage.getItem("token"))return;const now=Date.now();if(now-lastActivityWrite<1000)return;lastActivityWrite=now;localStorage.setItem(ACTIVITY_KEY,String(now))}
function startInactivityMonitor(){for(const eventName of ["pointerdown","pointermove","keydown","touchstart","scroll"])window.addEventListener(eventName,recordActivity,{passive:true});setInterval(()=>{if(!localStorage.getItem("token"))return;const last=Number(localStorage.getItem(ACTIVITY_KEY)||0);if(last&&Date.now()-last>=INACTIVITY_LIMIT_MS)logout("ออกจากระบบอัตโนมัติ เนื่องจากไม่มีการใช้งานเป็นเวลา 15 นาที")},15000)}
function money(n){return Number(n||0).toLocaleString("th-TH")}
function hasPermission(key){return currentUser?.role==="admin"||currentUser?.permissions?.[key]===true}
function hasAnyPermission(list){return currentUser?.role==="admin"||String(list||"").split(",").some(key=>hasPermission(key.trim()))}
function showPage(id){const page=document.getElementById(id);if(!page||page.dataset.permission&&!hasPermission(page.dataset.permission)||page?.dataset.anyPermission&&!hasAnyPermission(page.dataset.anyPermission))return alert("คุณไม่มีสิทธิ์เข้าถึงหน้านี้");document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));page.classList.add("active");document.querySelector(".sidebar")?.classList.remove("mobile-open");if(id==="dashboardPage")loadDashboard();if(id==="bookingListPage")loadBookingList();if(id==="companyPage")loadCompanyProfileToForm();if(id==="masterDataPage")loadMasterDataPro("programs");if(id==="userPage")loadUsers();if(id==="permissionPage")loadPermissionMatrix();if(id==="printCenterPage")configureReportOptions();if(id==="financialPage"&&typeof loadFinancialPage==="function")loadFinancialPage();if(id==="auditPage")loadAuditLogs();}
function toggleMobileMenu(){document.querySelector(".sidebar")?.classList.toggle("mobile-open")}
async function login(){try{const u=document.getElementById("loginUsername").value.trim(),p=document.getElementById("loginPassword").value;const r=await API.login(u,p);localStorage.setItem("token",r.token);localStorage.setItem("user",JSON.stringify(r.user));localStorage.setItem(ACTIVITY_KEY,String(Date.now()));currentUser=r.user;applyAuth();if(r.user.mustChangePassword){showChangePassword(true,p);return}await initData();}catch(e){document.getElementById("loginError").innerText=e.message}}
function logout(reason=""){localStorage.clear();if(reason)alert(reason);location.reload()}
function closeAuthModals(){document.getElementById("changePasswordModal")?.classList.add("hidden");if(!currentUser)document.getElementById("loginScreen").style.display="flex"}
function showChangePassword(required=false,current=""){document.getElementById("changePasswordModal").classList.remove("hidden");document.getElementById("changePasswordCancel").classList.toggle("hidden",required);document.getElementById("changePasswordHint").innerText=required?"กรุณาตั้งรหัสผ่านเฉพาะของคุณก่อนใช้งานระบบ":"เปลี่ยนรหัสผ่านของบัญชีปัจจุบัน";document.getElementById("currentPassword").value=current}
async function submitPasswordChange(){const currentPassword=val("currentPassword"),newPassword=val("newPassword"),confirmPassword=val("newPasswordConfirm"),root=document.getElementById("changePasswordMessage");if(newPassword!==confirmPassword){root.innerText="รหัสผ่านใหม่ไม่ตรงกัน";return}try{await API.changePassword(currentPassword,newPassword);localStorage.clear();alert("เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบใหม่");location.href=location.pathname}catch(error){root.innerText=error.message}}
function applyAuth(){currentUser=JSON.parse(localStorage.getItem("user")||"null");document.getElementById("loginScreen").style.display=currentUser?"none":"flex";document.getElementById("userBox").innerHTML=currentUser?`<b>${escapeHtml(currentUser.displayName)}</b><br>Username: ${escapeHtml(currentUser.username)}<br>Role: ${escapeHtml(currentUser.role)}`:"";document.querySelectorAll("[data-permission]").forEach(el=>el.classList.toggle("permission-hidden",!hasPermission(el.dataset.permission)));document.querySelectorAll("[data-any-permission]").forEach(el=>el.classList.toggle("permission-hidden",!hasAnyPermission(el.dataset.anyPermission)));}
async function initData(){await loadMaster();startNewBooking();loadDashboard();}
async function loadMaster(){master=await API.master();populateBookingMasterSelects()}
function fillMasterSelect(id,rows,idField,nameField,{blank=false}={}){const select=document.getElementById(id),current=select?.value;if(!select)return;select.innerHTML=(blank?'<option value="">ไม่ระบุ</option>':"")+(rows||[]).map(row=>`<option value="${escapeHtml(row[nameField])}">${escapeHtml(row[nameField])}</option>`).join("");if(current&&[...select.options].some(option=>option.value===current))select.value=current}
function populateBookingMasterSelects(){fillMasterSelect("source",master.customerSources,"source_id","source_name");fillMasterSelect("transportationMethod",master.transportationMethods,"method_id","method_name",{blank:true});for(const id of ["paymentMethod","depositPaymentMethod","creditPaymentMethod"])fillMasterSelect(id,master.paymentMethods,"method_id","method_name",{blank:id!=="paymentMethod"})}
function ensurePaymentMethod(id){const select=document.getElementById(id);if(select&&!select.value&&select.options.length>1)select.selectedIndex=1}
function toggleReturnDate(){const r=document.getElementById("tripType").value==="round_trip";document.getElementById("returnDate").disabled=!r;if(!r)document.getElementById("returnDate").value=""}
function programPriceForType(program,passengerType){if(passengerType==="foc")return 0;if(passengerType==="child")return Number(program.child_price??program.default_price??0);if(passengerType==="infant")return Number(program.infant_price??program.default_price??0);return Number(program.default_price||0)}
function createPassenger(i=0,passengerType="adult"){const pr=master.programs?.[0]||{program_id:"boat_ticket",program_name:"ตั๋วเรือ",default_price:1500,child_price:1500,infant_price:1500},price=programPriceForType(pr,passengerType);return{title:i===0?document.getElementById("leaderTitle").value:"",firstName:i===0?document.getElementById("leaderFirstName").value:"",lastName:i===0?document.getElementById("leaderLastName").value:"",age:"",phone:i===0?document.getElementById("phone").value:"",passengerType,nationalityType:"thai",pickupLocation:"",transportationMethod:"",transportationAmount:0,island:"",foodAllergy:"",medicalNote:"",accommodationId:"",accommodationName:"",accommodationBookedBy:"customer",parkAccommodationReference:"",parkAccommodationNote:"",tentCreditAmount:0,isLeader:i===0,program:{programId:pr.program_id,name:pr.program_name,qty:1,price,defaultPrice:price,priceReason:passengerType==="foc"?"FOC":"ราคา Default ตามประเภทผู้โดยสาร"},preAddOns:(master.addOns||[]).map(a=>({id:a.addon_id,name:a.addon_name,selected:false,qty:1,price:Number(a.default_price),defaultPrice:Number(a.default_price)})),islandAddOns:[]}}
const passengerTypeLabels={adult:"ผู้ใหญ่",child:"เด็ก",infant:"ทารก",foc:"FOC"};
function updatePassengerCountInputs(){const counts={adult:0,child:0,infant:0,foc:0};for(const person of passengers)counts[person.passengerType||"adult"]++;document.getElementById("adultCount").value=Math.max(counts.adult,1);document.getElementById("childCount").value=counts.child;document.getElementById("infantCount").value=counts.infant;document.getElementById("focCount").value=counts.foc;document.getElementById("paxCount").value=passengers.length}
function syncPassengerComposition(){const counts={adult:Math.max(Number(val("adultCount")||1),1),child:Math.max(Number(val("childCount")||0),0),infant:Math.max(Number(val("infantCount")||0),0),foc:Math.max(Number(val("focCount")||0),0)},types=Object.entries(counts).flatMap(([type,count])=>Array(count).fill(type));if(types.length<passengers.length&&!confirm("จำนวนผู้เดินทางลดลง รายการผู้โดยสารส่วนเกินจะถูกนำออก ต้องการดำเนินการต่อหรือไม่?")){updatePassengerCountInputs();return}const unused=[...passengers],next=types.map((type,index)=>{let found=unused.findIndex(person=>(person.passengerType||"adult")===type);if(found<0)found=unused.length?0:-1;const isNew=found<0,person=isNew?createPassenger(index,type):unused.splice(found,1)[0],previous=person.passengerType||"adult";person.passengerType=type;person.isLeader=index===0;if(!isNew&&previous!==type){const program=master.programs.find(item=>item.program_id===person.program.programId)||{};person.program.price=programPriceForType(program,type);person.program.defaultPrice=person.program.price;person.program.priceReason=type==="foc"?"FOC":"ราคา Default ตามประเภทผู้โดยสาร"}return person});passengers=next;updatePassengerCountInputs();renderPassengers();refreshSummary()}
function parsePassengerText(){const result=parseSmartPasteText(document.getElementById("passengerText").value);if(!result.ok)return alert(`${result.error}\nตัวอย่าง: 1. นาย สมชาย ใจดี`);const previous=[...passengers];passengers=result.passengers.map((person,index)=>{const passengerType=previous[index]?.passengerType||(["เด็กชาย","เด็กหญิง"].includes(person.title)?"child":"adult");return{...createPassenger(index,passengerType),...person,passengerType,isLeader:index===0}});const leader=passengers[0];document.getElementById("leaderTitle").value=leader.title;document.getElementById("leaderFirstName").value=leader.firstName;document.getElementById("leaderLastName").value=leader.lastName;updatePassengerCountInputs();renderPassengers();refreshSummary();}
function renderPassengers(){const root=document.getElementById("passengerList");root.innerHTML=passengers.map((p,pi)=>`<div class="passenger-card"><h3>${pi+1}. ${p.isLeader?"หัวหน้าทริป":""}</h3><div class="form-grid"><div><label>คำนำหน้า</label><select onchange="passengers[${pi}].title=this.value">${["","นาย","นาง","นางสาว","เด็กชาย","เด็กหญิง"].map(x=>`<option ${p.title===x?"selected":""}>${x}</option>`).join("")}</select></div><div><label>ชื่อ</label><input value="${p.firstName||""}" oninput="passengers[${pi}].firstName=this.value;refreshSummary()"></div><div><label>นามสกุล</label><input value="${p.lastName||""}" oninput="passengers[${pi}].lastName=this.value;refreshSummary()"></div><div><label>อายุ</label><input value="${p.age||""}" oninput="passengers[${pi}].age=this.value"></div><div><label>เบอร์</label><input value="${p.phone||""}" oninput="passengers[${pi}].phone=this.value"></div><div><label>เกาะ</label><select onchange="passengers[${pi}].island=this.value"><option></option><option ${p.island==="อ่าวไม้งาม"?"selected":""}>อ่าวไม้งาม</option><option ${p.island==="อ่าวช่องขาด"?"selected":""}>อ่าวช่องขาด</option></select></div><div><label>ที่พักอุทยาน (ไม่รวมรายได้)</label><select onchange="passengers[${pi}].parkAccommodationType=this.value"><option value="none" ${(p.parkAccommodationType||"none")==="none"?"selected":""}>ไม่นอน</option><option value="park_house" ${p.parkAccommodationType==="park_house"?"selected":""}>บ้านพักอุทยาน</option><option value="park_tent" ${p.parkAccommodationType==="park_tent"?"selected":""}>เต็นท์อุทยาน</option></select></div><div><label>ผู้จองที่พัก</label><select onchange="passengers[${pi}].parkAccommodationBookedBy=this.value"><option value="customer" ${(p.parkAccommodationBookedBy||"customer")==="customer"?"selected":""}>ลูกค้าจองเอง</option><option value="park" ${p.parkAccommodationBookedBy==="park"?"selected":""}>อุทยานจัดให้</option><option value="unknown" ${p.parkAccommodationBookedBy==="unknown"?"selected":""}>ไม่ระบุ</option></select></div><div><label>เลขอ้างอิงที่พัก</label><input value="${escapeHtml(p.parkAccommodationReference||"")}" oninput="passengers[${pi}].parkAccommodationReference=this.value"></div><div><label>หมายเหตุที่พัก</label><input value="${escapeHtml(p.parkAccommodationNote||"")}" oninput="passengers[${pi}].parkAccommodationNote=this.value"></div></div><div class="service"><b>Program</b><select onchange="changeProgram(${pi},this.value)">${(master.programs||[]).map(pr=>`<option value="${pr.program_id}" ${p.program.programId===pr.program_id?"selected":""}>${pr.program_name} - ${money(pr.default_price)}</option>`).join("")}</select><div class="form-grid"><div><label>Qty</label><input type="number" value="${p.program.qty}" onchange="passengers[${pi}].program.qty=Number(this.value||1);refreshSummary()"></div><div><label>Price</label><input type="number" value="${p.program.price}" onchange="passengers[${pi}].program.price=Number(this.value||0);refreshSummary()"></div></div></div><div class="service"><b>Pre Add-on / อุปกรณ์เบิก</b>${(p.preAddOns||[]).map((a,ai)=>`<div class="line"><label><input type="checkbox" ${a.selected?"checked":""} onchange="passengers[${pi}].preAddOns[${ai}].selected=this.checked;refreshSummary()"> ${a.name}</label><span><input style="width:70px" type="number" value="${a.qty}" onchange="passengers[${pi}].preAddOns[${ai}].qty=Number(this.value||1);refreshSummary()"> <input style="width:90px" type="number" value="${a.price}" onchange="passengers[${pi}].preAddOns[${ai}].price=Number(this.value||0);refreshSummary()"></span></div>`).join("")}</div><div class="service"><b>Island Add-on</b>${(p.islandAddOns||[]).map(a=>`<div class="line"><span>${a.name} x ${a.qty}</span><b>${money(a.qty*a.price)}</b></div>`).join("")}<button class="btn soft" onclick="addIslandAddon(${pi})">เพิ่มซื้อบนเกาะ</button></div></div>`).join("")}
function setPassengerAccommodation(index,field,value){const person=passengers[index];if(field==="tentCreditAmount")person[field]=Math.max(Number(value||0),0);else person[field]=value;if(field==="accommodationId")person.accommodationName=master.accommodations?.find(item=>item.accommodation_id===value)?.accommodation_name||"";refreshSummary()}
function changeProgram(pi,id){const pr=master.programs.find(x=>x.program_id===id);if(!pr)return;const type=passengers[pi].passengerType||"adult",price=programPriceForType(pr,type);passengers[pi].program={programId:pr.program_id,name:pr.program_name,qty:1,price,defaultPrice:price,priceReason:type==="foc"?"FOC":"ราคา Default ตามประเภทผู้โดยสาร"};if(id!=="boat_ticket")passengers[pi].preAddOns.forEach(item=>item.selected=false);renderPassengers();refreshSummary();}
function copyLeaderPackage(pi){if(pi===0||!passengers[0])return;passengers[pi].program=structuredClone(passengers[0].program);const type=passengers[pi].passengerType||"adult",program=master.programs.find(item=>item.program_id===passengers[pi].program.programId)||{},price=programPriceForType(program,type);passengers[pi].program.price=price;passengers[pi].program.defaultPrice=price;passengers[pi].program.priceReason=type==="foc"?"FOC":"ราคา Default ตามประเภทผู้โดยสาร";passengers[pi].preAddOns=structuredClone(passengers[0].preAddOns);renderPassengers();refreshSummary();}
function copyLeaderPackageToAll(){if(passengers.length<2)return alert("ยังไม่มีผู้โดยสารคนอื่นให้คัดลอก");if(!confirm(`คัดลอก Program และ Add-on จากหัวหน้าทริปไปยังผู้โดยสารอีก ${passengers.length-1} คนหรือไม่?\nราคาจะคำนวณตามประเภทผู้ใหญ่ เด็ก ทารก และ FOC ของแต่ละคน`))return;for(let index=1;index<passengers.length;index++){const person=passengers[index],type=person.passengerType||"adult",program=master.programs.find(item=>item.program_id===passengers[0].program.programId)||{};person.program=structuredClone(passengers[0].program);person.program.price=programPriceForType(program,type);person.program.defaultPrice=person.program.price;person.program.priceReason=type==="foc"?"FOC":"ราคา Default ตามประเภทผู้โดยสาร";person.preAddOns=structuredClone(passengers[0].preAddOns)}renderPassengers();refreshSummary();alert(`คัดลอกให้ ${passengers.length-1} คนแล้ว`)}
function addLeaderApplyAllButton(){const card=document.querySelector("#passengerList .passenger-card");if(!card||card.querySelector(".copy-leader-package-all"))return;const button=document.createElement("button");button.type="button";button.className="btn soft copy-leader-package-all";button.textContent="คัดลอก Program/Add-on ให้ผู้โดยสารทุกคน";button.addEventListener("click",copyLeaderPackageToAll);card.querySelector("h3")?.after(button)}
function addIslandAddon(pi){const name=prompt("รายการ");if(!name)return;const qty=Number(prompt("จำนวน",1)||1),price=Number(prompt("ราคา",0)||0);passengers[pi].islandAddOns.push({id:"other",name,qty,price,defaultPrice:price,paymentMethod:"เงินสด",receivedBy:currentUser?.displayName||""});renderPassengers();refreshSummary();}
function personTotal(p){return Math.max(Number(p.program.qty||1)*Number(p.program.price||0)-Number(p.tentCreditAmount||0),0)+Math.max(Number(p.transportationAmount||0),0)+(p.preAddOns||[]).filter(a=>a.selected).reduce((s,a)=>s+Number(a.qty||1)*Number(a.price||0),0)+(p.islandAddOns||[]).reduce((s,a)=>s+Number(a.qty||1)*Number(a.price||0),0)}
function applyPassengerBusinessRules(){document.querySelectorAll("#passengerList .passenger-card").forEach((card,index)=>{const person=passengers[index];if(index>0&&!card.querySelector(".copy-leader-package")){const button=document.createElement("button");button.type="button";button.className="btn soft copy-leader-package";button.textContent="คัดลอก Program/Add-on จากหัวหน้าทริป";button.addEventListener("click",()=>copyLeaderPackage(index));card.querySelector("h3")?.after(button)}card.querySelectorAll(".form-grid>div").forEach(div=>{const label=div.querySelector("label")?.textContent||"";if(["ที่พักอุทยาน","ผู้จองที่พัก","เลขอ้างอิงที่พัก","หมายเหตุที่พัก"].some(text=>label.includes(text)))div.classList.add("hidden")});if(!card.querySelector(".accommodation-simple")){const box=document.createElement("div"),programSection=card.querySelector(".service");box.className="service accommodation-simple";box.innerHTML=`<b>ที่พัก</b><div class="form-grid"><div><label>ที่พัก</label><select onchange="setPassengerAccommodation(${index},'accommodationId',this.value)"><option value="">ไม่ระบุ</option>${(master.accommodations||[]).map(item=>`<option value="${item.accommodation_id}" ${person.accommodationId===item.accommodation_id?"selected":""}>${escapeHtml(item.accommodation_name)}</option>`).join("")}</select></div><div><label>ผู้จองที่พัก</label><select onchange="setPassengerAccommodation(${index},'accommodationBookedBy',this.value)"><option value="customer" ${(person.accommodationBookedBy||"customer")==="customer"?"selected":""}>ลูกค้าจองเอง</option><option value="company" ${person.accommodationBookedBy==="company"?"selected":""}>จองให้</option></select></div><div><label>เครดิตคืนค่าเต็นท์</label><input type="number" min="0" step="0.01" value="${Number(person.tentCreditAmount||0)}" onchange="setPassengerAccommodation(${index},'tentCreditAmount',this.value)"></div></div></div>`;programSection?.after(box)}const preSection=card.querySelectorAll(".service")[2],locked=person?.program?.programId!=="boat_ticket";if(preSection){preSection.querySelectorAll("input").forEach(input=>input.disabled=locked);preSection.title=locked?"Package รวมบริการ Pre Add-on แล้ว":""}})}
function refreshSummary(){let total=0;const passengerLines=passengers.map((p,i)=>{const t=personTotal(p);total+=t;return`<div class="line"><span>${i+1}. ${[p.title,p.firstName,p.lastName].filter(Boolean).join(" ")||"ยังไม่กรอกชื่อ"} (${passengerTypeLabels[p.passengerType||"adult"]})</span><b>${money(t)}</b></div>`}).join(""),deposit=Math.max(Number(val("depositAmount")||0),0),credit=Math.max(Number(val("creditAmount")||0),0);document.getElementById("summary").innerHTML=passengerLines+`<div class="line"><span>มัดจำ</span><b>${money(deposit)}</b></div><div class="line"><span>ขายเชื่อ</span><b>${money(credit)}</b></div><div class="line"><span>คงเหลือหลังมัดจำ/ขายเชื่อ</span><b>${money(Math.max(total-deposit-credit,0))}</b></div>`;document.getElementById("grandTotal").innerText=money(total);applyPassengerBusinessRules();applyPassengerLogisticsFields();document.querySelectorAll("#passengerList .passenger-card").forEach((card,index)=>{const person=passengers[index],type=person?.passengerType||"adult";card.querySelector("h3").textContent=`${index+1}. ${index===0?"หัวหน้าทริป":`ผู้โดยสารคนที่ ${index+1}`} (${passengerTypeLabels[type]})`;const select=card.querySelector(".service select");if(select)[...select.options].forEach(option=>{const program=master.programs.find(item=>item.program_id===option.value);if(program)option.textContent=`${program.program_name} - ${money(programPriceForType(program,type))}`})})}

function setPassengerLogistics(index,field,value){const person=passengers[index];if(field==="transportationAmount")person[field]=Math.max(Number(value||0),0);else person[field]=value;if(field==="transportationMethod"){const method=(master.transportationMethods||[]).find(item=>item.method_name===value);person.transportationAmount=Number(method?.default_price||0);renderPassengers();refreshSummary()}else refreshSummary()}
function applyPassengerLogisticsFields(){document.querySelectorAll("#passengerList .passenger-card").forEach((card,index)=>{if(card.querySelector(".passenger-logistics"))return;const person=passengers[index],box=document.createElement("div");box.className="service passenger-logistics";box.innerHTML=`<b>สัญชาติและการรับส่ง</b><div class="form-grid"><div><label>สัญชาติ</label><select onchange="setPassengerLogistics(${index},'nationalityType',this.value)"><option value="thai" ${(person.nationalityType||"thai")==="thai"?"selected":""}>ไทย</option><option value="foreign" ${person.nationalityType==="foreign"?"selected":""}>ต่างชาติ</option></select></div><div><label>สถานที่ให้ไปรับ</label><input value="${escapeHtml(person.pickupLocation||"")}" onchange="setPassengerLogistics(${index},'pickupLocation',this.value)"></div><div><label>วิธีการเดินทาง</label><select onchange="setPassengerLogistics(${index},'transportationMethod',this.value)"><option value="">ไม่ระบุ</option>${(master.transportationMethods||[]).map(item=>`<option value="${escapeHtml(item.method_name)}" ${person.transportationMethod===item.method_name?"selected":""}>${escapeHtml(item.method_name)} - ${money(item.default_price||0)}</option>`).join("")}</select></div><div><label>ค่าเดินทาง</label><input type="number" min="0" step="0.01" value="${Number(person.transportationAmount||0)}" onchange="setPassengerLogistics(${index},'transportationAmount',this.value)"></div></div>`;card.querySelector(".service")?.before(box)})}
function buildBooking(){const leaderTitle=val("leaderTitle"),leaderFirstName=val("leaderFirstName"),leaderLastName=val("leaderLastName"),phone=val("phone");if(passengers[0]&&!passengers[0].firstName&&!passengers[0].lastName){passengers[0].title=leaderTitle;passengers[0].firstName=leaderFirstName;passengers[0].lastName=leaderLastName;passengers[0].phone=phone;passengers[0].isLeader=true}const total=passengers.reduce((s,p)=>s+personTotal(p),0);const pr=passengers.reduce((s,p)=>s+Math.max(Number(p.program.qty||1)*Number(p.program.price||0)-Number(p.tentCreditAmount||0),0),0);const pre=passengers.reduce((s,p)=>s+(p.preAddOns||[]).filter(a=>a.selected).reduce((x,a)=>x+Number(a.qty||1)*Number(a.price||0),0),0);const isl=passengers.reduce((s,p)=>s+(p.islandAddOns||[]).reduce((x,a)=>x+Number(a.qty||1)*Number(a.price||0),0),0);const depositAmount=Math.max(Number(val("depositAmount")||0),0),creditAmount=Math.max(Number(val("creditAmount")||0),0);if(depositAmount&&!val("depositPaymentMethod"))throw new Error("กรุณาเลือกช่องทางมัดจำ");if(creditAmount&&!val("creditPaymentMethod"))throw new Error("กรุณาเลือกช่องทางรับชำระยอดเชื่อ");return{bookingCode:editingCode||"BK"+Date.now(),tripType:val("tripType"),travelDate:val("travelDate"),returnDate:val("returnDate"),leaderTitle,leaderFirstName,leaderLastName,phone,contactEmail:val("contactEmail"),source:val("source"),agentName:val("agentName"),transportationMethod:val("transportationMethod"),status:val("status"),paymentMethod:val("paymentMethod"),depositAmount,depositPaymentMethod:val("depositPaymentMethod"),creditAmount,creditPaymentMethod:val("creditPaymentMethod"),receiptBookNo:val("receiptBookNo"),manualReceiptNo:val("manualReceiptNo"),bookingNote:val("bookingNote"),passengers,totalAmount:total,programRevenue:pr,preAddOnRevenue:pre,islandAddOnRevenue:isl}}
function val(id){return document.getElementById(id)?.value||""}
function validateBooking(b){if(b.travelDate&&b.returnDate&&b.returnDate<b.travelDate)return"วันเดินทางกลับต้องไม่ก่อนวันเดินทาง";if(!`${b.leaderFirstName||""}${b.leaderLastName||""}`.trim())return"กรุณาระบุชื่อหัวหน้าทริป";if(!b.phone.trim())return"กรุณาระบุเบอร์โทรหัวหน้าทริป";if(b.depositAmount&&!b.depositPaymentMethod)return"กรุณาเลือกช่องทางมัดจำ";if(b.creditAmount&&!b.creditPaymentMethod)return"กรุณาเลือกช่องทางรับชำระยอดเชื่อ";return""}
async function saveBooking(){const b=buildBooking(),error=validateBooking(b);if(error)return alert(error);const dup=await API.duplicate(b);if(dup.duplicates?.length){const detail=dup.duplicates.map(x=>`${x.bookingCode}: ${x.name||x.phone||"ข้อมูลซ้ำ"}`).join("\n");if(!confirm(`พบข้อมูลที่อาจเป็น Booking ซ้ำ\n${detail}\n\nต้องการบันทึกต่อหรือไม่?`))return;}await API.saveBooking(b);editingCode=b.bookingCode;document.getElementById("saveNewBtn").classList.add("hidden");document.getElementById("saveEditBtn").classList.remove("hidden");alert("บันทึกแล้ว ระบบเปลี่ยนเป็นโหมดแก้ไขเพื่อป้องกันการสร้างซ้ำ");await loadBookingList();}
async function updateBooking(){if(!editingCode)return alert("ยังไม่ได้เลือก Booking");const b=buildBooking(),error=validateBooking(b);if(error)return alert(error);await API.updateBooking(editingCode,b);alert("อัปเดตแล้ว");}
async function cancelBooking(){if(!editingCode)return alert("ยังไม่ได้เลือก Booking");const reason=prompt("เหตุผลยกเลิก");if(!reason)return;await API.cancelBooking(editingCode,reason);alert("ยกเลิกแล้ว");}
function startNewBooking(){editingCode=null;selectedBooking=null;for(const id of ["travelDate","returnDate","leaderFirstName","leaderLastName","phone","contactEmail","agentName","receiptBookNo","manualReceiptNo","bookingNote","passengerText"])document.getElementById(id).value="";document.getElementById("tripType").value="one_way";document.getElementById("leaderTitle").value="";document.getElementById("status").value="confirmed";document.getElementById("depositAmount").value="0";document.getElementById("creditAmount").value="0";populateBookingMasterSelects();for(const id of ["transportationMethod","depositPaymentMethod","creditPaymentMethod"])document.getElementById(id).value="";toggleReturnDate();passengers=[createPassenger(0,"adult")];updatePassengerCountInputs();renderPassengers();refreshSummary();document.getElementById("saveNewBtn").classList.remove("hidden");document.getElementById("saveEditBtn").classList.add("hidden");}
async function openNewBooking(){try{await loadMaster()}catch(error){return alert(`โหลด Master Data ไม่สำเร็จ: ${error.message}`)}startNewBooking();showPage("bookingPage")}
async function loadBookingList(){bookings=await API.bookings();const d=val("blDate"),dateMode=val("blDateMode"),st=val("blStatus"),q=val("blSearch").trim().toLocaleLowerCase("th-TH");let rows=bookings;if(d)rows=rows.filter(b=>dateMode==="travel"?b.travelDate===d:dateMode==="return"?b.returnDate===d:b.travelDate===d||b.returnDate===d);if(st)rows=rows.filter(b=>b.status===st);if(q)rows=rows.filter(b=>bookingSearchText(b).includes(q));document.getElementById("bookingList").innerHTML=rows.map(b=>`<div class="booking-item" onclick='selectBooking(${JSON.stringify(b).replace(/'/g,"&apos;")})'><span class="status-badge status-${b.status}">${b.status}</span><b>${b.bookingCode}</b><br>${[b.leaderFirstName,b.leaderLastName].filter(Boolean).join(" ")}<br>ไป ${b.travelDate||"ยังไม่ระบุ"} | กลับ ${b.returnDate||"ยังไม่ระบุ"} | ${b.passengers?.length||0} คน | ${money(b.totalAmount)} บาท</div>`).join("")||"ไม่พบข้อมูล";}
function bookingSearchText(booking){return[booking.bookingCode,booking.receiptBookNo,booking.manualReceiptNo,booking.leaderTitle,booking.leaderFirstName,booking.leaderLastName,booking.phone,booking.contactEmail,booking.source,booking.agentName,booking.transportationMethod,booking.paymentMethod,booking.status,...(booking.passengers||[]).flatMap(person=>[person.title,person.firstName,person.lastName,person.phone])].filter(Boolean).join(" ").toLocaleLowerCase("th-TH")}
function clearBookingListFilters(){document.getElementById("blDate").value="";document.getElementById("blDateMode").value="any";document.getElementById("blStatus").value="";document.getElementById("blSearch").value="";loadBookingList()}
function selectBooking(b){selectedBooking=b;const deposit=Number(b.depositAmount||0),balance=Math.max(Number(b.totalAmount||0)-deposit,0);document.getElementById("bookingDetail").innerHTML=`<h2>${b.bookingCode}</h2><p>${[b.leaderFirstName,b.leaderLastName].filter(Boolean).join(" ")}</p><p>${b.travelDate||"ยังไม่ระบุวัน"} | ${b.status}</p><p>โทร: ${b.phone||"-"}${b.contactEmail?` | ติดต่อได้จาก: ${b.contactEmail}`:""}</p><p>ช่องทาง: ${b.source||"-"} | วิธีเดินทาง: ${b.transportationMethod||"-"} | ชำระเงิน: ${b.paymentMethod||"-"}</p><p>เล่มที่: ${b.receiptBookNo||"-"} | เลขที่: ${b.manualReceiptNo||"-"}</p><p>ยอดรวม ${money(b.totalAmount)} บาท | มัดจำ ${money(deposit)} บาท | คงเหลือ ${money(balance)} บาท</p>${(b.passengers||[]).map((p,i)=>`<div class="service">${i+1}. ${[p.firstName,p.lastName].filter(Boolean).join(" ")||"ยังไม่ระบุชื่อลูกทัวร์"} - ${p.program?.name||""}</div>`).join("")}`;}
function editSelectedBooking(){if(!selectedBooking)return;loadBookingToForm(selectedBooking);showPage("bookingPage")}
function backToBookingEditor(){if(selectedBooking)return editSelectedBooking();if(editingCode)return showPage("bookingPage");alert("กรุณาเลือก Booking ที่ต้องการแก้ไข")}
function setSelectValueWithHistory(id,value){const select=document.getElementById(id);if(!select)return;if(value&&![...select.options].some(option=>option.value===value))select.add(new Option(`${value} (รายการเดิม)`,value));select.value=value||""}
function loadBookingToForm(b){editingCode=b.bookingCode;["tripType","travelDate","returnDate","leaderTitle","leaderFirstName","leaderLastName","phone","contactEmail","agentName","status","depositAmount","creditAmount","receiptBookNo","manualReceiptNo","bookingNote"].forEach(id=>{const el=document.getElementById(id);if(el)el.value=b[id]??""});for(const id of ["source","transportationMethod","paymentMethod","depositPaymentMethod","creditPaymentMethod"])setSelectValueWithHistory(id,b[id]);passengers=b.passengers?.length?b.passengers.map((person,index)=>({...person,passengerType:person.passengerType||"adult",nationalityType:person.nationalityType||"thai",transportationAmount:Number(person.transportationAmount||0),isLeader:index===0})):[createPassenger(0,"adult")];updatePassengerCountInputs();toggleReturnDate();renderPassengers();refreshSummary();document.getElementById("saveNewBtn").classList.add("hidden");document.getElementById("saveEditBtn").classList.remove("hidden");}
async function loadTimeline(){if(!selectedBooking)return;const logs=await API.timeline(selectedBooking.bookingCode);document.getElementById("timelineRoot").innerHTML=logs.map(x=>`<div class="service"><b>${x.action}</b><br>${x.detail||""}<br><span class="muted">${x.changed_at||""}</span></div>`).join("")||"ไม่มี timeline";}
async function loadDashboard(){try{bookings=await API.bookings();const today=new Date().toISOString().slice(0,10);const rows=bookings.filter(b=>b.travelDate===today);document.getElementById("kpiBookings").innerText=rows.length;document.getElementById("kpiPax").innerText=rows.reduce((s,b)=>s+(b.passengers?.length||0),0);document.getElementById("kpiRevenue").innerText=money(rows.reduce((s,b)=>s+Number(b.totalAmount||0),0));document.getElementById("kpiCheckin").innerText=rows.filter(b=>b.status==="checked-in").length;document.getElementById("dashboardBookings").innerHTML=rows.map(b=>`<div class="line"><span>${b.bookingCode} ${b.leaderFirstName}</span><b>${money(b.totalAmount)}</b></div>`).join("")||"ไม่มี booking วันนี้";}catch(e){}}
function localIsoDate(date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function applyReportPeriod(){const from=val("pcDate"),period=val("pcPeriod");if(!from)return;const start=new Date(`${from}T00:00:00`),end=new Date(start);if(period==="week")end.setDate(end.getDate()+6);else if(period==="month")end.setMonth(end.getMonth()+1,0);else if(period==="day"){}else return;document.getElementById("pcToDate").value=localIsoDate(end)}
function managementIncomeMatrix(matrix,range){if(!matrix?.length)return"";const dates=Object.keys(matrix[0].values||{});return`<h2>ตารางสรุปรายได้ ${escapeHtml(range?.from||"")} – ${escapeHtml(range?.to||"")}</h2><div class="table-scroll"><table class="data-table management-matrix"><thead><tr><th>รายการ</th>${dates.map(date=>`<th>${escapeHtml(date)}</th>`).join("")}</tr></thead><tbody>${matrix.map(row=>`<tr><th>${escapeHtml(row.category)}</th>${dates.map(date=>`<td>${money(row.values[date])}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function excelDate(value){if(!value)return"";const date=new Date(String(value).includes("T")?value:`${value}T00:00:00`);return Number.isNaN(date.getTime())?value:date.toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"2-digit"})}
function excelCell(value){const text=String(value??"").replace(/"/g,'""');return `"${text}"`}
function bookingExcelRow(booking){const people=booking.passengers||[],counts={child:0,foc:0};for(const person of people){const type=person.passengerType||"adult";if(type==="child"||type==="infant")counts.child++;if(type==="foc")counts.foc++}const programs=[...new Set(people.map(person=>person.program?.name).filter(Boolean))].join(", "),travel=[...new Set(people.map(person=>person.transportationMethod).filter(Boolean))].join(", ")||booking.transportationMethod||"",lodging=[...new Set(people.map(person=>person.accommodationName).filter(Boolean))].join(", ");return[booking.agentName||getCompanySettings().company_name||"ซาบีน่า",booking.source||"",excelDate(booking.createdAt),booking.receiptBookNo||"",booking.manualReceiptNo||"",booking.boatTicketNo||"",[booking.leaderTitle,booking.leaderFirstName,booking.leaderLastName].filter(Boolean).join(" "),booking.phone||"",people.length,counts.child,counts.foc,programs,Number(booking.totalAmount||0),Number(booking.depositAmount||0),excelDate(booking.travelDate),excelDate(booking.returnDate),travel,"",lodging,booking.contactEmail||"",booking.bookingNote||""]}
async function exportBookingExcel(){const from=val("pcDate"),to=val("pcToDate")||from;if(!from)return alert("เลือกวันที่เริ่มต้น");if(to<from)return alert("วันที่สิ้นสุดต้องไม่น้อยกว่าวันเริ่มต้น");try{const rows=(await API.bookings()).filter(booking=>booking.status!=="cancelled"&&booking.travelDate>=from&&booking.travelDate<=to);const headers=["ต้นฉบับ","จองในงาน","วันที่จอง","เล่มที่","เลขที่","เลขตั๋วเรือ","ชื่อลูกค้า","เบอร์โทร","จำนวน","เด็ก","FOC","โปรแกรม","ราคาขาย","มัดจำ","วันมา","วันกลับ","เดินทางโดย","เดินทางกลับ","ที่พัก","ช่องทางติดต่อ","หมายเหตุ"];const csv="\uFEFF"+[headers,...rows.map(bookingExcelRow)].map(row=>row.map(excelCell).join(",")).join("\r\n"),blob=new Blob([csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`Sabina-Booking-${from}-${to}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(error){alert(error.message||"ดาวน์โหลด Excel ไม่สำเร็จ")}}
async function generatePrintCenterReport(){
  const date=val("pcDate"),to=val("pcToDate")||date,type=val("pcType");
  if(!date)return alert("เลือกวันที่");
  if(to<date)return alert("วันที่สิ้นสุดต้องไม่น้อยกว่าวันเริ่มต้น");
  try{
    const r=await API.report(date,type,to),summary=r.summary||{};
    document.getElementById("printCenterOutput").classList.remove("hidden");
    const equipmentRows=r.equipment||[],accommodation=r.accommodation||{};
    const kpis=type==="management"?[
      ["Booking วันนี้",summary.bookings],["จำนวนคนวันนี้",summary.pax],["ลงเกาะ",summary.arrivals],["ขึ้นจากเกาะ",summary.departures],
      ["รายได้คาดการณ์วันนี้",money(summary.expectedRevenue)],["รับเงินจริงวันนี้",money(summary.actualReceived)],["ค้างรับวันนี้",money(summary.outstanding)],["คาดการณ์รวม 7 วัน",money(summary.sevenDayExpected)],["เครดิตค่าเต็นท์ 7 วัน",money(summary.sevenDayTentCredit)]
    ]:[
      ["Bookings",summary.bookings],["จำนวนคน/รายการ",summary.pax],["ลงเกาะ",summary.arrivals],["ขึ้นจากเกาะ",summary.departures],["รายได้คาดการณ์",money(summary.expectedRevenue)]
    ];
    document.getElementById("printCenterOutput").innerHTML=`
      <div class="document-actions">
        <button class="btn primary" onclick="window.print()">Print / Save PDF</button>
      </div>
      <div class="report-paper">
        <div class="report-header">
          <div>
            <h1>${escapeHtml(r.title||type||"Report")}</h1>
            <div>${escapeHtml(r.purpose||"")}</div>
            <div>Date: ${escapeHtml(date)}${r.range?` — ${escapeHtml(r.range.to)}`:""}</div>
          </div>
          <div>${escapeHtml(getCompanySettings().company_name||"Sabina Tour Booking")}</div>
        </div>
        <div class="report-kpis">${kpis.map(([label,value])=>`<div class="report-kpi"><span>${escapeHtml(label)}</span><b>${escapeHtml(value??0)}</b></div>`).join("")}</div>
        <div class="workspace report-operations">
          <div>
            <h2>ยอดอุปกรณ์ที่ต้องเบิก</h2>
            ${equipmentRows.length?reportTable(equipmentRows):"<p>ไม่มีอุปกรณ์ที่ต้องเบิก</p>"}
          </div>
          <div>
            <h2>ที่พักอุทยาน (ไม่รวมรายได้บริษัท)</h2>
            <div class="report-kpis">
              <div class="report-kpi"><span>บ้านพักอุทยาน</span><b>${Number(accommodation.parkHouse||0)} คน</b></div>
              <div class="report-kpi"><span>เต็นท์อุทยาน</span><b>${Number(accommodation.parkTent||0)} คน</b></div>
              <div class="report-kpi"><span>ไม่นอน</span><b>${Number(accommodation.none||0)} คน</b></div>
              <div class="report-kpi"><span>ลูกค้าจองเอง</span><b>${Number(accommodation.customerSelfBooked||0)} คน</b></div>
              <div class="report-kpi"><span>เครดิตคืนค่าเต็นท์</span><b>${money(accommodation.tentCreditDue||0)} บาท</b></div>
            </div>
          </div>
        </div>
        ${type==="management"?managementIncomeMatrix(r.incomeMatrix,r.range):""}
        ${reportTable(r.rows||[])}
        <div class="muted">Generated: ${new Date().toLocaleString("th-TH")}</div>
      </div>
    `;
  }catch(error){document.getElementById("printCenterOutput").innerHTML=`<div class="error">${escapeHtml(error.message||"สร้างรายงานไม่สำเร็จ")}</div>`}
}
function configureReportOptions(){const select=document.getElementById("pcType");[...select.options].forEach(option=>{option.hidden=!hasAnyPermission(option.dataset.anyPermission);option.disabled=option.hidden});if(select.selectedOptions[0]?.disabled)select.value=[...select.options].find(option=>!option.disabled)?.value||""}
const reportColumnLabels={date:"วันที่",direction:"ทิศทาง",bookingCode:"Booking",leader:"หัวหน้ากลุ่ม",passenger:"ชื่อผู้โดยสาร",age:"อายุ",phone:"โทรศัพท์",pax:"จำนวนคน",program:"โปรแกรม",island:"เกาะ",accommodation:"ที่พักอุทยาน",accommodationBookedBy:"ผู้จองที่พัก",accommodationReference:"เลขอ้างอิง",accommodationArrangement:"รูปแบบที่พัก",tentCreditAmount:"เครดิตค่าเต็นท์",foodAllergy:"แพ้อาหาร",medicalNote:"ข้อมูลสุขภาพ",status:"สถานะ",paymentMethod:"ช่องทางชำระ",totalAmount:"ยอดจอง",agent:"ช่องทาง/Agent",note:"หมายเหตุ",bookings:"Bookings",pending:"รอยืนยัน",confirmed:"ยืนยันแล้ว",checkedIn:"Check-in",parkHouse:"บ้านพัก",parkTent:"เต็นท์",equipmentUnits:"อุปกรณ์เบิก",tentCreditDue:"เครดิตค่าเต็นท์",expectedRevenue:"รายได้คาดการณ์",actualReceived:"รับเงินจริง",outstanding:"ค้างรับ",code:"รหัส",name:"อุปกรณ์",qty:"จำนวนเบิก"};
Object.assign(reportColumnLabels,{email:"ติดต่อได้จาก",passengerType:"ประเภทผู้โดยสาร",transportationMethod:"วิธีการเดินทาง",depositAmount:"มัดจำ",balanceAmount:"คงเหลือ",deposits:"มัดจำ",receiptBookNo:"เล่มที่",manualReceiptNo:"เลขที่"});
Object.assign(reportColumnLabels,{nationality:"สัญชาติ",pickupLocation:"สถานที่ให้ไปรับ",transportationAmount:"ค่าเดินทาง",depositPaymentMethod:"ช่องทางมัดจำ",creditAmount:"ขายเชื่อ",creditPaymentMethod:"ช่องทางรับชำระยอดเชื่อ"});
Object.assign(reportColumnLabels,{boatTicketBookNo:"เล่มที่ (ตั๋วเรือ)",boatTicketNo:"เลขที่ (ตั๋วเรือ)"});
const reportMoneyColumns=new Set(["totalAmount","depositAmount","creditAmount","transportationAmount","balanceAmount","deposits","tentCreditAmount","tentCreditDue","expectedRevenue","actualReceived","outstanding"]);
function reportTable(rows){if(!rows.length)return"<p>ไม่มีข้อมูลสำหรับวันที่เลือก</p>";const keys=Object.keys(rows[0]);return`<div class="table-scroll"><table class="data-table"><thead><tr>${keys.map(key=>`<th>${escapeHtml(reportColumnLabels[key]||key)}</th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr>${keys.map(key=>`<td>${escapeHtml(reportMoneyColumns.has(key)?money(row[key]):row[key]??"")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function table(rows){if(!rows.length)return"ไม่มีข้อมูล";const keys=Object.keys(rows[0]);return`<table class="data-table"><thead><tr>${keys.map(k=>`<th>${k}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${r[k]??""}</td>`).join("")}</tr>`).join("")}</tbody></table>`}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function getCompanySettings(){return JSON.parse(localStorage.getItem("company_profile")||"null")||{company_name:"Dive Tour Company",phone:"",address:"",tax_id:""}}
function receiptItems(b){
  const grouped=new Map();
  const add=(key,item)=>{const current=grouped.get(key);if(current){current.qty+=item.qty;current.total+=item.total}else grouped.set(key,item)};
  (b.passengers||[]).forEach(p=>{
    if(p.program){
      const qty=Number(p.program.qty||1), price=Number(p.program.price||0);
      const nationality=p.nationalityType==="foreign"?"ต่างชาติ":"",type=passengerTypeLabels[p.passengerType||"adult"],label=`${type}${nationality}`;
      add(`program:${label}:${p.program.name}:${price}`,{name:label,detail:p.program.name||"ค่าตั๋วเรือ/โปรแกรม",qty,unit:price,total:qty*price});
      if(Number(p.tentCreditAmount||0)>0)add(`tent-credit:${p.tentCreditAmount}`,{name:"เครดิตคืนค่าเต็นท์",detail:"ลูกค้าจองที่พักเอง",qty:1,unit:-Number(p.tentCreditAmount),total:-Number(p.tentCreditAmount)});
    }
    (p.preAddOns||[]).filter(a=>a.selected).forEach(a=>{
      const qty=Number(a.qty||1), price=Number(a.price||0);
      add(`equipment:${a.name}:${price}`,{name:`ค่าอุปกรณ์- ${a.name}`,detail:"",qty,unit:price,total:qty*price});
    });
    (p.islandAddOns||[]).forEach(a=>{
      const qty=Number(a.qty||1), price=Number(a.price||0);
      add(`equipment:${a.name}:${price}`,{name:`ค่าอุปกรณ์- ${a.name}`,detail:a.paymentMethod||"",qty,unit:price,total:qty*price});
    });
    if(Number(p.transportationAmount||0)>0)add(`transport:${p.transportationMethod}:${p.transportationAmount}`,{name:"ค่าเดินทาง",detail:p.transportationMethod||"",qty:1,unit:Number(p.transportationAmount),total:Number(p.transportationAmount)});
  });
  return [...grouped.values()];
}

function renderReceipt(b,type="RECEIPT"){
  const c=getCompanySettings();
  const items=receiptItems(b);
  const subtotal=items.reduce((s,x)=>s+Number(x.total||0),0);
  const total=Number(b.totalAmount||subtotal||0);
  const logo=c.logo_url||c.logoUrl
    ? `<img class="document-logo" src="${c.logo_url||c.logoUrl}" onerror="this.style.display='none'">`
    : `<div class="document-logo-placeholder"></div>`;

  return `
    <div class="document-actions">
      <button class="btn primary" onclick="window.print()">Print / Save PDF</button>
      <button class="btn soft" onclick="window.close()">Close</button>
    </div>

    <div class="document-page">
      <div class="document-header">
        <div class="document-company">
          ${logo}
          <div>
            <h2>${c.company_name||"Dive Tour Company"}</h2>
            <div>${c.address||""}</div>
            <div>Tel: ${c.phone||"-"}</div>
            <div>Tax ID: ${c.tax_id||"-"}</div>
          </div>
        </div>
        <div class="document-title">
          <h1>${type}</h1>
          <div>เล่มที่: ${b.receiptBookNo||"-"} / เลขที่: ${b.manualReceiptNo||b.receiptNo||"RC-"+(b.bookingCode||"DRAFT")}</div>
          <div>เล่มที่ (ตั๋วเรือ): ${escapeHtml(b.boatTicketBookNo||"-")} / เลขที่ (ตั๋วเรือ): ${escapeHtml(b.boatTicketNo||"-")}</div>
          <div>Booking: ${b.bookingCode||"DRAFT"}</div>
          <div>Date: ${new Date().toISOString().slice(0,10)}</div>
        </div>
      </div>

      <div class="document-meta">
        <div class="document-box">
          <strong>ข้อมูลติดต่อการจอง</strong><br>
          หัวหน้าทริป: ${escapeHtml([b.leaderTitle,b.leaderFirstName,b.leaderLastName].filter(Boolean).join(" ")||"-")}<br>
          Phone: ${escapeHtml(b.phone||"-")}<br>
          Contact: ${escapeHtml(b.contactEmail||"-")}<br>
          Source: ${escapeHtml(b.source||"-")}<br>
          Agent: ${escapeHtml(b.agentName||"-")}
        </div>
        <div class="document-box">
          <strong>Trip Detail</strong><br>
          Travel Date: ${b.travelDate||"-"}<br>
          Return Date: ${b.returnDate||"-"}<br>
          Transportation: ${b.transportationMethod||"-"}<br>
          Status: ${b.status||"-"}<br>
          Payment: ${b.paymentMethod||"-"}
        </div>
      </div>

      <table class="document-table">
        <thead>
          <tr>
            <th>รายการ</th>
            <th style="width:80px">Qty</th>
            <th style="width:120px">Unit</th>
            <th style="width:130px">Amount</th>
          </tr>
        </thead>
        <tbody>
          ${items.map(x=>`
            <tr>
              <td>${escapeHtml(x.name)}${x.detail?`<br><span class="muted">${escapeHtml(x.detail)}</span>`:""}</td>
              <td class="num">${x.qty}</td>
              <td class="num">${money(x.unit)}</td>
              <td class="num">${money(x.total)}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>

      <div class="document-total">
        <div class="document-total-row"><span>Subtotal</span><b>${money(subtotal)}</b></div>
        <div class="document-total-row grand"><span>Total</span><b>${money(total)} บาท</b></div>
        <div class="document-total-row"><span>มัดจำ (${escapeHtml(b.depositPaymentMethod||b.paymentMethod||"-")})</span><b>${money(Number(b.depositAmount||0))} บาท</b></div>
        <div class="document-total-row"><span>ขายเชื่อ (${escapeHtml(b.creditPaymentMethod||"-")})</span><b>${money(Number(b.creditAmount||0))} บาท</b></div>
        <div class="document-total-row"><span>คงเหลือ</span><b>${money(Math.max(total-Number(b.depositAmount||0)-Number(b.creditAmount||0),0))} บาท</b></div>
      </div>

      <div class="document-note">
        <strong>Payment Info:</strong>
        ${[c.bank_name,c.bank_account,c.bank_account_name,c.promptpay?`PromptPay: ${c.promptpay}`:""].filter(Boolean).join(" | ")||"-"}
        ${b.bookingNote?`<br><strong>Note:</strong> ${b.bookingNote}`:""}
      </div>

      ${type==="RECEIPT"?`<div class="paid-stamp">PAID</div>`:""}

      <div class="document-footer">
        <div><div class="signature-line">ผู้รับเงิน / Staff</div></div>
        <div><div class="signature-line">ลูกค้า / Customer</div></div>
      </div>
    </div>
  `;
}

function openPrintDoc(html,title="Document"){
  const w=window.open("","_blank");
  w.document.write(`
    <html>
      <head>
        <title>${title}</title>
        <link rel="stylesheet" href="css/style.css">
      </head>
      <body class="print-only-body">${html}</body>
    </html>
  `);
  w.document.close();
}

function printSelectedReceipt(type="RECEIPT"){
  if(!selectedBooking)return alert("เลือก booking ก่อน");
  openPrintDoc(renderReceipt(selectedBooking,type),`${type} ${selectedBooking.bookingCode}`);
}

function printCurrentReceipt(){
  const b=buildBooking();
  openPrintDoc(renderReceipt(b,"RECEIPT"),`RECEIPT ${b.bookingCode||"DRAFT"}`);
}

