let mdCat="programs",mdRows=[];async function loadMasterDataPro(cat){mdCat=cat;const config=masterDataConfig[cat];document.getElementById("mdpTitle").innerText=cat;mdRows=await API.mdp(cat);const priceHead=config.tiered?"<th>ผู้ใหญ่</th><th>เด็ก</th><th>ทารก</th>":config.price?"<th>ราคา Default</th>":"";document.getElementById("masterDataProRoot").innerHTML=`<table class="data-table"><thead><tr><th>Code</th><th>ชื่อ</th>${priceHead}<th>Active</th><th>Sort</th><th>รายละเอียด</th><th></th></tr></thead><tbody>${mdRows.map((row,index)=>`<tr><td>${escapeHtml(row[config.id]||"")}</td><td>${escapeHtml(row[config.name]||"")}</td>${config.tiered?`<td>${money(row.default_price)}</td><td>${money(row.child_price)}</td><td>${money(row.infant_price)}</td>`:config.price?`<td>${money(row[config.price])}</td>`:""}<td>${row.active_flag?"✓":"✗"}</td><td>${Number(row.sort_order||0)}</td><td>${escapeHtml(row.description||"")}</td><td><button class="btn soft" onclick="editMasterDataProItem(${index})">แก้ไข</button></td></tr>`).join("")}</tbody></table>`}
