function closeCsvImport(){document.getElementById("csvImportModal").classList.add("hidden")}
async function previewPassengerCsv(file){if(!file)return;const text=await file.text(),result=parsePassengerCsv(text);csvImportResult=result;const counts={adult:0,child:0,infant:0,foc:0};result.rows.forEach(row=>counts[row.passengerType]++);const warnings=[...(result.errors||[]),...(result.duplicates||[])];document.getElementById("csvImportSummary").innerHTML=`<div class="csv-summary"><b>${result.rows.length} คน</b> · ผู้ใหญ่ ${counts.adult} · เด็ก ${counts.child} · ทารก ${counts.infant} · FOC ${counts.foc}</div>${warnings.length?`<div class="error">${warnings.map(escapeHtml).join("<br>")}</div>`:"<div class='audit-ok'>ตรวจรูปแบบผ่าน พร้อมนำเข้า</div>"}`;document.getElementById("csvImportPreview").innerHTML=result.rows.length?`<table class="data-table"><thead><tr><th>แถว</th><th>ชื่อ-สกุล</th><th>ประเภท</th><th>สัญชาติ</th><th>โทร</th><th>โปรแกรม</th><th>จุดรับ/เดินทาง</th></tr></thead><tbody>${result.rows.map(row=>`<tr><td>${row.sourceRow}</td><td>${escapeHtml([row.title,row.firstName,row.lastName].filter(Boolean).join(" "))}</td><td>${escapeHtml(passengerTypeLabels[row.passengerType])}</td><td>${row.nationalityType==="foreign"?"ต่างชาติ":"ไทย"}</td><td>${escapeHtml(row.phone)}</td><td>${escapeHtml(row.programName)}</td><td>${escapeHtml([row.pickupLocation,row.transportationMethod].filter(Boolean).join(" / "))}</td></tr>`).join("")}</tbody></table>`:"";document.getElementById("confirmCsvImportBtn").disabled=!result.ok||!result.rows.length||result.duplicates.length>0}
function importedPassenger(row,index){const person=createPassenger(index,row.passengerType),program=(master.programs||[]).find(item=>String(item.program_name).trim().toLowerCase()===String(row.programName).trim().toLowerCase()),accommodation=(master.accommodations||[]).find(item=>String(item.accommodation_name).trim().toLowerCase()===String(row.accommodationName).trim().toLowerCase());Object.assign(person,row,{isLeader:index===0});if(program){const price=programPriceForType(program,row.passengerType);person.program={programId:program.program_id,name:program.program_name,qty:1,price,defaultPrice:price,priceReason:"ราคา Default ตามประเภทผู้โดยสาร"}}if(accommodation){person.accommodationId=accommodation.accommodation_id;person.accommodationName=accommodation.accommodation_name}person.accommodationBookedBy=String(row.accommodationBookedBy).includes("จองให้")?"company":"customer";delete person.programName;delete person.sourceRow;return person}
function confirmPassengerCsvImport(){if(!csvImportResult?.ok||!csvImportResult.rows.length)return;const append=val("csvImportMode")==="append",start=append?passengers.length:0,next=csvImportResult.rows.map((row,index)=>importedPassenger(row,start+index));passengers=append?[...passengers,...next]:next;passengers.forEach((person,index)=>person.isLeader=index===0);const leader=passengers[0];if(leader){document.getElementById("leaderTitle").value=leader.title||"";document.getElementById("leaderFirstName").value=leader.firstName||"";document.getElementById("leaderLastName").value=leader.lastName||"";if(leader.phone)document.getElementById("phone").value=leader.phone}updatePassengerCountInputs();renderPassengers();refreshSummary();closeCsvImport();alert(`นำเข้ารายชื่อ ${next.length} คนแล้ว กรุณาตรวจ Preview ในการ์ดผู้เดินทางก่อนบันทึก Booking`)}
function downloadPassengerCsvTemplate(){const header="คำนำหน้า,ชื่อ,นามสกุล,อายุ,เบอร์โทร,ประเภทผู้โดยสาร,สัญชาติ,โปรแกรม,จุดรับ,วิธีเดินทาง,ค่าเดินทาง,ที่พัก,ผู้จองที่พัก,เครดิตค่าเต็นท์,แพ้อาหาร,ข้อมูลสุขภาพ",sample="นาย,สมชาย,ใจดี,35,0812345678,ผู้ใหญ่,ไทย,ตั๋วเรือ,บขส.,รถตู้,400,,ลูกค้าจองเอง,0,,";const blob=new Blob(["\uFEFF"+header+"\r\n"+sample],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="passenger-import-template.csv";link.click();URL.revokeObjectURL(url)}
const refreshSummaryBeforeBulk=refreshSummary;refreshSummary=function(){refreshSummaryBeforeBulk();addLeaderApplyAllButton()};
const startNewBookingBase=startNewBooking,loadBookingToFormBase=loadBookingToForm,bookingSearchTextBase=bookingSearchText,selectBookingBase=selectBooking;
startNewBooking=function(){startNewBookingBase();for(const id of ["boatTicketBookNo","boatTicketNo"])document.getElementById(id).value=""};
loadBookingToForm=function(booking){loadBookingToFormBase(booking);document.getElementById("boatTicketBookNo").value=booking.boatTicketBookNo||"";document.getElementById("boatTicketNo").value=booking.boatTicketNo||""};
bookingSearchText=function(booking){return `${bookingSearchTextBase(booking)} ${booking.boatTicketBookNo||""} ${booking.boatTicketNo||""}`.toLocaleLowerCase("th-TH")};
selectBooking=function(booking){selectBookingBase(booking);document.getElementById("bookingDetail").insertAdjacentHTML("beforeend",`<p>เล่มที่ (ตั๋วเรือ): ${escapeHtml(booking.boatTicketBookNo||"-")} | เลขที่ (ตั๋วเรือ): ${escapeHtml(booking.boatTicketNo||"-")}</p>`)};
(async()=>{startInactivityMonitor();applyAuth();if(currentUser){const last=Number(localStorage.getItem(ACTIVITY_KEY)||0);if(last&&Date.now()-last>=INACTIVITY_LIMIT_MS){logout("ออกจากระบบอัตโนมัติ เนื่องจากไม่มีการใช้งานเป็นเวลา 15 นาที");return}recordActivity()}if(currentUser?.mustChangePassword){showChangePassword(true);return}if(currentUser)await initData();})();
